    [Fact]
    public void DespawnHonorsArchetypeFilters()
    {
        using var world = new World();

        world.Spawn().Add(ValA.New(10));
        world.Spawn().Add(ValA.New(20)).Add("doomed");
        world.Spawn().Add(ValA.New(30)).Add("doomed");

        var all = world.Stream<ValA>();
        Assert.Equal(3, all.Count);

        all.Has(Comp<string>.Plain).Despawn();

        Assert.Equal(1, all.Count);
        all.For((ref c0) => Assert.Equal(10, c0.Value));
    }

    [Fact]
    public void DespawnHonorsPredicates()
    {
        using var world = new World();

        // an empty archetype exercises the empty-join skip during collection
        var dead = world.Spawn().Add(ValA.New(0)).Add(0.25f);
        world.Despawn(dead);

        world.Spawn().Add(ValA.New(10));
        world.Spawn().Add(ValA.New(90));
        world.Spawn().Add(ValA.New(95)).Add("extended");
        world.Spawn().Add(ValA.New(99)).Add(42L); // sheltered by the Not clause
        var outsider = world.Spawn().Add("outsider");

        var filtered = world.Stream<ValA>()
            .Not(Comp<long>.Plain)
            .Where((in ValA c) => c.Value > 50);
        Assert.Equal(2, filtered.Count);

        filtered.Despawn();

        Assert.Equal(0, filtered.Count);
        Assert.Equal(2, world.Stream<ValA>().Count);
        Assert.True(outsider.Alive);
        world.Stream<ValA>().For((ref c0) => Assert.True(c0.Value is 10 or 99));
    }

