        for (var i = 0; i < 100; i++) world.Spawn().Add(ValA.New(7)).Add("tag");
        for (var i = 0; i < 50; i++) world.Spawn().Add(ValA.New(8));

        var filtered = world.Stream<ValA>().Has(Comp<string>.Plain);

        var visited = 0;
        filtered.Job((ref c0) =>
        {
            Interlocked.Increment(ref visited);
            Assert.Equal(7, c0.Value);
        });
        Assert.Equal(100, visited);

        visited = 0;
        filtered.Job(4711, (uniform, ref c0) =>
        {
            Assert.Equal(4711, uniform);
            Interlocked.Increment(ref visited);
            Assert.Equal(7, c0.Value);
        });
        Assert.Equal(100, visited);
    }

    [Fact]
    public void WildcardOperationsThrow()
    {
        using var world = new World();
        world.Spawn().Add(ValA.New(1));

        var filtered = world.Query<ValA>(Match.Any).Stream().Where((in ValA c) => c.Value > 0);

        Assert.Throws<InvalidOperationException>(() => filtered.Job((ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1, (uniform, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (ref _) => { },
            (ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (in e, ref _) => { },
            (in e, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, ref _) => { },
            (uniform, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, in e, ref _) => { },
            (uniform, in e, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Job(
            (ref _) => { },
            (ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1,
            (uniform, ref _) => { },
            (uniform, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Despawn());
    }
