    [Fact]
    public void DespawnHonorsArchetypeFilters()
    {
        using var world = new World();

        world.Spawn().Add(ValA.New(10)).Add(ValB.New(10));
        world.Spawn().Add(ValA.New(20)).Add(ValB.New(20)).Add("doomed");
        world.Spawn().Add(ValA.New(30)).Add(ValB.New(30)).Add("doomed");

        var all = world.Stream<ValA, ValB>();
