    [Fact]
    public void DespawnHonorsPredicates()
    {
        using var world = new World();

        // an empty archetype exercises the empty-join skip during collection
        var dead = world.Spawn().Add(ValA.New(0)).Add(ValB.New(0)).Add(0.25f);
        world.Despawn(dead);

        world.Spawn().Add(ValA.New(10)).Add(ValB.New(10));
        world.Spawn().Add(ValA.New(90)).Add(ValB.New(90));
        world.Spawn().Add(ValA.New(95)).Add(ValB.New(95)).Add("extended");
        world.Spawn().Add(ValA.New(99)).Add(ValB.New(99)).Add(42L); // sheltered by the Not clause
        var outsider = world.Spawn().Add("outsider");

        var filtered = world.Stream<ValA, ValB>()
            .Not(Comp<long>.Plain)
            .Where((in ValA c) => c.Value > 50);
        Assert.Equal(2, filtered.Count);

        filtered.Despawn();

        Assert.Equal(0, filtered.Count);
        Assert.Equal(2, world.Stream<ValA, ValB>().Count);
        Assert.True(outsider.Alive);
        world.Stream<ValA, ValB>().For((ref c0, ref _) => Assert.True(c0.Value is 10 or 99));
    }

    [Fact]
    public void EmptyFiltersBehaveLikeStream()
    {
        using var world = new World();

        world.Spawn().Add(ValA.New(1)).Add(ValB.New(1));
        world.Spawn().Add(ValA.New(2)).Add(ValB.New(2)).Add("extended");

        var all = world.Stream<ValA, ValB>();
        var unfiltered = all.Has();

        Assert.Equal(all.Count, unfiltered.Count);

        var included = 0;
        var excluded = 0;
        unfiltered.For(
            (ref _, ref _) => { included++; },
            (ref _, ref _) => { excluded++; });
        Assert.Equal(all.Count, included);
        Assert.Equal(0, excluded);

        Assert.NotEmpty(unfiltered.ToString());
    }

    [Fact]
    public void UnderlyingStreamDropsDown()
    {
        using var world = new World();

        world.Spawn().Add(ValA.New(10)).Add(ValB.New(10));
        world.Spawn().Add(ValA.New(90)).Add(ValB.New(90));

        var all = world.Stream<ValA, ValB>();
        var filtered = all.Where((in ValA c) => c.Value > 50);

        Assert.Equal(1, filtered.Count);
        Assert.True(filtered.Stream == all);
        Assert.Equal(2, filtered.Stream.Count);

        var visited = 0;
        filtered.Stream.For((ref _, ref _) => { visited++; });
        Assert.Equal(2, visited);
    }

    [Fact]
    public void JobWithArchetypeFiltersOnly()
    {
        using var world = new World();

        for (var i = 0; i < 100; i++) world.Spawn().Add(ValA.New(7)).Add(ValB.New(7)).Add("tag");
        for (var i = 0; i < 50; i++) world.Spawn().Add(ValA.New(8)).Add(ValB.New(8));

        var filtered = world.Stream<ValA, ValB>().Has(Comp<string>.Plain);

        var visited = 0;
        filtered.Job((ref c0, ref _) =>
        {
            Interlocked.Increment(ref visited);
            Assert.Equal(7, c0.Value);
        });
        Assert.Equal(100, visited);

        visited = 0;
        filtered.Job(4711, (uniform, ref c0, ref _) =>
        {
            Assert.Equal(4711, uniform);
            Interlocked.Increment(ref visited);
            Assert.Equal(7, c0.Value);
        });
        Assert.Equal(100, visited);
    }

    [Fact]
    public void WildcardOperationsThrow()
    {
        using var world = new World();
        world.Spawn().Add(ValA.New(1)).Add(ValB.New(1));

        var filtered = world.Query<ValA, ValB>(Match.Any).Stream().Where((in ValA c) => c.Value > 0);

        Assert.Throws<InvalidOperationException>(() => filtered.Job((ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1, (uniform, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (ref _, ref _) => { },
            (ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (in e, ref _, ref _) => { },
            (in e, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, ref _, ref _) => { },
            (uniform, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, in e, ref _, ref _) => { },
            (uniform, in e, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Job(
            (ref _, ref _) => { },
            (ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1,
            (uniform, ref _, ref _) => { },
            (uniform, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Despawn());
    }
}

