    [Fact]
    public void WildcardOperationsThrow()
    {
        using var world = new World();
        world.Spawn().Add(ValA.New(1)).Add(ValB.New(1)).Add(ValC.New(1)).Add(ValD.New(1)).Add(ValE.New(1));

        var filtered = world.Query<ValA, ValB, ValC, ValD, ValE>(Match.Any).Stream().Where((in ValA c) => c.Value > 0);

        Assert.Throws<InvalidOperationException>(() => filtered.Job((ref _, ref _, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1, (uniform, ref _, ref _, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (ref _, ref _, ref _, ref _, ref _) => { },
            (ref _, ref _, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (in e, ref _, ref _, ref _, ref _, ref _) => { },
            (in e, ref _, ref _, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, ref _, ref _, ref _, ref _, ref _) => { },
            (uniform, ref _, ref _, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, in e, ref _, ref _, ref _, ref _, ref _) => { },
            (uniform, in e, ref _, ref _, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Job(
            (ref _, ref _, ref _, ref _, ref _) => { },
            (ref _, ref _, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1,
            (uniform, ref _, ref _, ref _, ref _, ref _) => { },
            (uniform, ref _, ref _, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Despawn());
    }
