    public void TwoDelegateUniformJobPartitions(int count)
    {
        using var world = new World();

        // an empty archetype exercises the empty-join skip in the runners
        var dead = world.Spawn().Add(RefA.New(0)).Add(0.25f);
        world.Despawn(dead);

        for (var i = 0; i < count; i++)
        {
            world.Spawn().Add(RefA.New(Random.Shared.Next(100)));
        }

        var all = world.Stream<RefA>();

        // split on component 0 (RefA)
        var split0 = all.Where((in RefA c) => c.Value > 50);

        var included0 = 0;
        var excluded0 = 0;
        split0.Job(4711,
            (uniform, ref c0) =>
