        });
        Assert.Equal(100, visited);
    }

    [Fact]
    public void WildcardOperationsThrow()
    {
        using var world = new World();
        world.Spawn().Add(RefA.New(1)).Add(RefB.New(1)).Add(RefC.New(1));

        var filtered = world.Query<RefA, RefB, RefC>(Match.Any).Stream().Where((in RefA c) => c.Value > 0);

        Assert.Throws<InvalidOperationException>(() => filtered.Job((ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1, (uniform, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (ref _, ref _, ref _) => { },
            (ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(
            (in e, ref _, ref _, ref _) => { },
            (in e, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, ref _, ref _, ref _) => { },
            (uniform, ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.For(1,
            (uniform, in e, ref _, ref _, ref _) => { },
            (uniform, in e, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Job(
            (ref _, ref _, ref _) => { },
            (ref _, ref _, ref _) => { }));
        Assert.Throws<InvalidOperationException>(() => filtered.Job(1,
            (uniform, ref _, ref _, ref _) => { },
            (uniform, ref _, ref _, ref _) => { }));

        Assert.Throws<InvalidOperationException>(() => filtered.Despawn());
    }
