                Assert.True(c3.Value > 50);
            },
            (uniform, ref _, ref _, ref _, ref c3) =>
            {
                Assert.Equal(4711, uniform);
                Interlocked.Increment(ref excluded3);
                Assert.True(c3.Value <= 50);
            });

        Assert.Equal(count, included3 + excluded3);
    }

    [Fact]
    public void TwoDelegatesCoverPrunedArchetypes()
    {
        using var world = new World();

        // three archetypes: bare, +string (half passing the predicate), +string+long
        for (var i = 0; i < 3; i++) world.Spawn().Add(RefA.New(10)).Add(RefB.New(10)).Add(RefC.New(10)).Add(RefD.New(10));
        for (var i = 0; i < 4; i++) world.Spawn().Add(RefA.New(i % 2 == 0 ? 90 : 10)).Add(RefB.New(i % 2 == 0 ? 90 : 10)).Add(RefC.New(i % 2 == 0 ? 90 : 10)).Add(RefD.New(i % 2 == 0 ? 90 : 10)).Add("tag");
        for (var i = 0; i < 5; i++) world.Spawn().Add(RefA.New(10)).Add(RefB.New(10)).Add(RefC.New(10)).Add(RefD.New(10)).Add("tag").Add(42L);

        var all = world.Stream<RefA, RefB, RefC, RefD>();
        Assert.Equal(12, all.Count);

        var filtered = all
            .Has(Comp<string>.Plain)
            .Not(Comp<long>.Plain)
            .Where((in RefA c) => c.Value > 50);
        Assert.Equal(2, filtered.Count);

        // all four For variants: excluded must see the pruned archetypes AND the failing entities
        var included = 0;
        var excluded = 0;
        filtered.For(
            (ref c0, ref _, ref _, ref _) => { included++; Assert.True(c0.Value > 50); },
            (ref _, ref _, ref _, ref _) => { excluded++; });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);

        included = 0;
        excluded = 0;
        filtered.For(
            (in e, ref c0, ref _, ref _, ref _) => { Assert.True(e.Alive); included++; },
            (in e, ref _, ref _, ref _, ref _) => { Assert.True(e.Alive); excluded++; });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);

        included = 0;
        excluded = 0;
        filtered.For(4711,
            (uniform, ref c0, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); included++; },
            (uniform, ref _, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); excluded++; });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);

        included = 0;
        excluded = 0;
        filtered.For(4711,
            (uniform, in e, ref c0, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); Assert.True(e.Alive); included++; },
            (uniform, in e, ref _, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); Assert.True(e.Alive); excluded++; });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);

        // both two-delegate Jobs: pruned archetypes are dispatched as unconditional work items
        included = 0;
        excluded = 0;
        filtered.Job(
            (ref c0, ref _, ref _, ref _) => { Interlocked.Increment(ref included); Assert.True(c0.Value > 50); },
            (ref _, ref _, ref _, ref _) => { Interlocked.Increment(ref excluded); });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);

        included = 0;
        excluded = 0;
        filtered.Job(4711,
            (uniform, ref c0, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); Interlocked.Increment(ref included); },
            (uniform, ref _, ref _, ref _, ref _) => { Assert.Equal(4711, uniform); Interlocked.Increment(ref excluded); });
        Assert.Equal(2, included);
        Assert.Equal(10, excluded);
    }

    [Fact]
    public void HasUsesAndSemantics()
    {
        using var world = new World();

        // four archetypes; only one has BOTH the string and the long component
        world.Spawn().Add(RefA.New(1)).Add(RefB.New(1)).Add(RefC.New(1)).Add(RefD.New(1));
        world.Spawn().Add(RefA.New(2)).Add(RefB.New(2)).Add(RefC.New(2)).Add(RefD.New(2)).Add("s");
        world.Spawn().Add(RefA.New(3)).Add(RefB.New(3)).Add(RefC.New(3)).Add(RefD.New(3)).Add(42L);
        world.Spawn().Add(RefA.New(4)).Add(RefB.New(4)).Add(RefC.New(4)).Add(RefD.New(4)).Add("s").Add(42L);

        var all = world.Stream<RefA, RefB, RefC, RefD>();
        var both = all.Has(Comp<string>.Plain, Comp<long>.Plain);

        // AND semantics: only the archetype with both components matches (OR would match 3)
        Assert.Equal(1, both.Count);

        var visited = 0;
        both.For((ref c0, ref _, ref _, ref _) =>
        {
            visited++;
            Assert.Equal(4, c0.Value);
        });
        Assert.Equal(1, visited);

        visited = 0;
        both.For((in e, ref c0, ref _, ref _, ref _) =>
        {
            Assert.True(e.Alive);
            visited++;
            Assert.Equal(4, c0.Value);
        });
        Assert.Equal(1, visited);

        visited = 0;
        both.For(4711, (uniform, ref c0, ref _, ref _, ref _) =>
        {
            Assert.Equal(4711, uniform);
            visited++;
            Assert.Equal(4, c0.Value);
        });
        Assert.Equal(1, visited);

        visited = 0;
        both.For(4711, (uniform, in e, ref c0, ref _, ref _, ref _) =>
        {
            Assert.Equal(4711, uniform);
            Assert.True(e.Alive);
            visited++;
            Assert.Equal(4, c0.Value);
        });
        Assert.Equal(1, visited);

        var enumerated = 0;
        foreach (var row in both)
        {
            enumerated++;
            Assert.Equal(4, row.Item2.Value);
        }
        Assert.Equal(1, enumerated);
    }

    [Fact]
    public void FiltersAccumulateAndPredicatesReplace()
    {
        using var world = new World();

        world.Spawn().Add(RefA.New(1)).Add(RefB.New(1)).Add(RefC.New(1)).Add(RefD.New(1));
        world.Spawn().Add(RefA.New(2)).Add(RefB.New(2)).Add(RefC.New(2)).Add(RefD.New(2)).Add("s");
        world.Spawn().Add(RefA.New(3)).Add(RefB.New(3)).Add(RefC.New(3)).Add(RefD.New(3)).Add(42L);
        world.Spawn().Add(RefA.New(4)).Add(RefB.New(4)).Add(RefC.New(4)).Add(RefD.New(4)).Add("s").Add(42L);

        var all = world.Stream<RefA, RefB, RefC, RefD>();

        // chained Has accumulates like a single multi-expression Has
        Assert.Equal(1, all.Has(Comp<string>.Plain).Has(Comp<long>.Plain).Count);
        Assert.Equal(all.Has(Comp<string>.Plain, Comp<long>.Plain).Count,
            all.Has(Comp<string>.Plain).Has(Comp<long>.Plain).Count);

        // chained Not accumulates like a single multi-expression Not
        Assert.Equal(1, all.Not(Comp<string>.Plain).Not(Comp<long>.Plain).Count);
        Assert.Equal(all.Not(Comp<string>.Plain, Comp<long>.Plain).Count,
            all.Not(Comp<string>.Plain).Not(Comp<long>.Plain).Count);

        // a second Where on the same component replaces the first predicate
        var replaced = all
            .Where((in RefA c) => c.Value > 1000)
            .Where((in RefA c) => c.Value >= 0);
        Assert.Equal(all.Count, replaced.Count);

        // Where predicates chained across components conjoin
        var conjunction = all            .Where((in RefA c) => c.Value >= 2)            .Where((in RefB c) => c.Value >= 2)            .Where((in RefC c) => c.Value >= 2)            .Where((in RefD c) => c.Value >= 2);
        Assert.Equal(3, conjunction.Count);
        Assert.NotEmpty(conjunction.ToString());
    }

    [Theory]
    [ClassData(typeof(StreamCountGenerator))]
    public void CountAndEnumerationHonorPredicates(int count, bool createEmptyTable)
    {
        using var world = new World();

        //Create an empty table by spawning and despawning a single entity
        //that matches our test Query (but is a larger Archetype)
        if (createEmptyTable)
        {
            var dead = world.Spawn().Add(RefA.New(0)).Add(RefB.New(0)).Add(RefC.New(0)).Add(RefD.New(0)).Add(0.25f);
            world.Despawn(dead);
        }

        var expected = 0;
        for (var index = 0; index < count; index++)
        {
            world.Spawn().Add(RefA.New(index % 100)).Add(RefB.New(index % 100)).Add(RefC.New(index % 100)).Add(RefD.New(index % 100));
            if (index % 100 > 50) expected++;
        }

        var filtered = world.Stream<RefA, RefB, RefC, RefD>().Where((in RefA c) => c.Value > 50);
        Assert.Equal(expected, filtered.Count);

        var seen = 0;
        foreach (var row in filtered)
        {
            seen++;
            Assert.True(row.Item2.Value > 50);
        }
        Assert.Equal(expected, seen);

        IEnumerable boxed = filtered;
        var boxedSeen = 0;
        foreach (var unused in boxed) boxedSeen++;
        Assert.Equal(expected, boxedSeen);
    }

